import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(6,1,{
 title:'视觉塔：一张图片怎样变成模型能用的表示',summary:'从像素数组开始，经过图像块、视觉编码器和连接层，跟踪每一步的形状。',prerequisites:['w2-l1','w2-l3'],
 terms:[T('视觉塔 vision tower','把图像转换为特征表示的视觉编码模块。','它可能输出一组图像块向量，不一定输出文字。'),T('patch 图像块','把图像分成的小区域。','224×224 图像按 16×16 切分，可以得到 14×14=196 个块。'),T('ViT 视觉 Transformer','把图像块变成向量，并使用 Transformer 处理的视觉结构。','视觉位置之间可以交换信息，形成上下文表示。'),T('connector/projector 连接层','把视觉特征的形状或语义接口转换到下游模型可接收的形式。','把每个 1024 维视觉向量投影成语言主干使用的 2048 维向量。')],
 sections:[P('第 1 步：图片先是数值，不是句子','一张 RGB 图片可以看成高×宽×3 的像素数组。模型输入还要经过缩放、裁剪和归一化等预处理。通道顺序可能是 HWC 或 CHW，范围可能是 0–255、0–1 或标准化后的数值。','同一图片使用错误的预处理，往往仍能得到形状合法的张量，但视觉特征会偏离训练时的分布。因此模型权重和预处理配置是一套接口。'),P('第 2 步：把图像变成一串块向量','ViT 常把图像切成 patch，展平每块像素，再做可学习投影，得到长度为 D 的向量。加上位置信息后，多个块经注意力交流，形成视觉表示。','有些实现额外加入分类 token，有些使用不同的块合并策略。196 只来自这里给定的分辨率与 patch 大小，不是所有视觉塔的固定输出长度。'),P('第 3 步：连接层解决接口不一致','视觉塔输出可能为 [B,N,Dv]，语言或动态主干期待 [B,N,Dm]。连接层可以将 Dv 转到 Dm，也可能重采样、减少 N。它的作用是对接，不应和整个视觉塔混为一谈。','一个线性连接层参数量约为 Dv×Dm（另有偏置时再加 Dm）。冻结视觉塔、训练连接层，表示只修改后者参数；视觉塔的前向计算仍存在。'),P('第 4 步：画出完整路径并验证','多模态理解路径可写成“像素→视觉塔→连接层→与文本结合→输出”。每个箭头写形状，旁边标记参数是否更新。这比只说“用了视觉模型”更具体。','提高图像分辨率可能增加视觉位置数，从而改变视觉和下游主干的计算量。先检查实际输出 shape，再估算资源；不能只看最后隐藏维度是否相同。')],
 worked:{title:'一张 224×224 图片的接口账本',steps:['patch 边长 16，每边 14 块，共 196 块，不考虑额外特殊位置。','每块输出 1024 维，视觉塔输出为 [1,196,1024]。','连接层映射到 2048 维，输出 [1,196,2048]。','只改连接层不等于不运行视觉塔，也不意味着它的权重不用放在内存。'],takeaway:'视觉塔负责提取表示；连接层负责把表示交给后续模块。'},
 example:{code:'height, width, patch = 224, 224, 16\nassert height % patch == 0 and width % patch == 0\npositions = (height//patch)*(width//patch)\nprint("visual shape", (1, positions, 1024))\nprint("projected shape", (1, positions, 2048))\nprint("linear weights", 1024*2048)',output:'visual shape (1, 196, 1024)\nprojected shape (1, 196, 2048)\nlinear weights 2097152',explanation:'这里只计算形状和参数量，不提取真实图片特征；真实输出长度要以具体编码器为准。'},
 checks:[Q('冻结视觉塔，是否意味着可以不运行它？','下游从哪里获得视觉特征？','不是。冻结表示不更新参数；若没有离线缓存特征，仍需执行前向计算。',2),Q('分辨率从 224 增到 448，patch 不变，块数变成多少？','每边块数都翻倍。','从 196 增到 784，数量变为四倍；不含额外特殊位置。',1)],
 practice:{title:'画一条没有黑箱的视觉前向路径',steps:[A('为给定分辨率计算 patch 数。','清楚写出是否含额外位置或重采样。','不能假设所有模型都使用 16×16 patch。'),A('画视觉塔和连接层，分别标形状与冻结状态。','两个模块的职责和更新范围清晰。','冻结不表示没有输出或不占内存。'),A('在实际项目中只读查找图像预处理和视觉输出 shape。','记录代码位置和已确认内容，未运行的标为待验证。','不要仅根据类名推断实际配置。')]},sources:[S.clip,S.llava,S.transformer]
}),
L(6,2,{
 title:'CLIP 与 DINO：不同监督怎样塑造视觉表示',summary:'先做一次图文匹配，再看只有图像时如何学习表示；区分“特征有用”和“任务已解决”。',prerequisites:['w6-l1','w3-l1'],
 terms:[T('对比学习 contrastive learning','鼓励匹配样本的表示更接近，并区分不匹配样本的一类学习方式。','配对图文应比同批次中不匹配图文有更高相似度。'),T('CLIP','通过图文对比目标学习关联的图像与文本表示的方法。','可比较图片与多个文字描述的相似度，但相似度不直接等于任务成功。'),T('DINO','一种自监督视觉表示学习方法，使用学生和教师对不同图像视图产生一致的预测。','没有人工类别标签，也仍有教师预测作为训练目标。'),T('教师—学生与 EMA','学生通过梯度学习；教师在某些方法中用学生参数的指数移动平均更新。','教师不是每个 batch 都直接复制学生，也不是必须由真人写标签。')],
 sections:[P('第 1 步：理解配对图文怎样提供监督','给一张猫的图片配上“猫坐在椅子上”，另有一张车和它的描述。图像、文本各经过编码器，得到可比较的表示。CLIP 类目标鼓励正确配对相似度较高。','错误配对会给出矛盾监督。若猫图总配汽车描述，增加步数不会自动修正语义。对你而言，配对质量、重复、难负例和描述覆盖都是算法目标的一部分。'),P('第 2 步：手算相似度的含义','为简化，令图像表示为 [1,0]，猫文本为 [1,0]，车文本为 [0,1]，归一化后点积分别为 1 与 0。这说明在这个表示里猫描述更匹配。','真实相似度受到编码器训练目标影响。文字中“左边两只猫”和“右边三只猫”可能很接近，模型未必正确计数或定位，因此不能把相似度当成事实核验。'),P('第 3 步：只有图像也能学习表示','DINO 给同一图像产生不同裁剪或视图，让学生预测与教师目标一致。教师目标的构造、停止梯度及防止表示塌缩的机制都很重要；不是简单让两个网络互相抄答案即可。','塌缩指不同图片都被映射到几乎相同的表示。若一味追求一致却不保留区分信息，模型可能得到很小的某种匹配误差，却失去使用价值。具体方法的中心化、锐化等细节需结合实现继续学习。'),P('第 4 步：用下游任务检验表示','冻结编码器，使用其表示做分类、检索或动态预测，是检查它是否保留所需信息的一种方式。若图像语义分类很好，但速度、接触或细小位置差异被忽略，世界模型仍可能失败。','因此选择视觉塔不能只看通用排行榜。先明确后续任务需要哪些信息，再用对应小任务对比不同表示；这连接到第 8 周的表征预测。')],
 worked:{title:'一张图与两段文字的匹配',steps:['先假设三个向量都已归一化。','图像 [1,0] 与“猫” [1,0] 点积为 1。','图像 [1,0] 与“车” [0,1] 点积为 0。','这只能支持在此表示下前者更接近，不能证明图片中所有细节都被准确理解。'],takeaway:'训练目标决定表示偏好保留什么，评测决定这些信息够不够用。'},
 example:{code:'def dot(a, b):\n    return sum(x*y for x,y in zip(a,b))\nimage = [1.0, 0.0]\ntexts = {"cat": [1.0, 0.0], "car": [0.0, 1.0]}\nfor label, vector in texts.items():\n    print(label, dot(image, vector))',output:'cat 1.0\ncar 0.0',explanation:'向量是人为给定的机制演示，不是运行 CLIP 得到的真实特征。'},
 checks:[Q('图文相似度很高，是否证明数量和左右关系都正确？','训练相似度是否逐项检查了这些细节？','不能。需要计数、关系或人工核验等任务评测补充。',1),Q('自监督 DINO 没有人工类别标签，是否没有训练目标？','目标来自教师在图像视图上的输出。','仍有目标，只是目标构造方式不同；自监督不等于无目标学习。',2)],
 practice:{title:'从数据匹配走到目标匹配',steps:[A('列出图文数据可能错配的三种原因。','例如时序偏移、描述对应错图、清洗后 ID 错位。','每个原因给一条可验证检查，别只写“噪声”。'),A('为世界模型列出表示必须保留的三类信息。','位置、运动、接触等按任务选择，而不是只列物体类别。','如果任务只需语义检索，需求会不同。'),A('设计一个冻结视觉编码器的小评测。','说明输入、目标、切分和简单基线。','不要求本课下载大模型；先把协议写完整。')]},sources:[S.clip,S.dino]
}),
L(6,3,{
 title:'视觉压缩：latent、VAE、离散 token 与项目 codec',summary:'把“能理解图像的特征”与“能还原图像的编码”分开，再定位世界模型前后的视觉接口。',prerequisites:['w6-l1','w6-l2'],
 terms:[T('latent 潜变量/隐表示','模型内部用于表示输入的一组数，具体含义由训练目标决定。','它可以是连续向量，也可以由离散编号表达。'),T('codec 编码解码模块','把原始数据压缩到某种表示，再从表示恢复输出的一组组件。','图像→编码器→latent→解码器→重建图像。'),T('VAE 变分自编码器','学习带概率约束的隐空间及解码器的一类模型。','除了重建目标，通常还有使隐分布接近先验的约束。'),T('VQ 向量量化','把连续表示映射到有限码本中的向量，常用码本编号作为离散表示。','像从有限词表里选图像块编号，但编号的含义由训练决定。'),T('LSD 项目术语','这里保留为需要按 OmniFM 的模块定义解释的名字，不把它当通用训练范式。','若实际接入的是视觉 codec，就沿编码、预测和解码接口定位职责。')],
 sections:[P('第 1 步：先问表示是否需要能解码','CLIP 类特征可能适合理解或检索，却不保证保留逐像素重建所需信息。若世界模型要预测未来图像，需要知道它预测的表示能否通过某个解码器变回图像。','编码器 E 把 x 变为 z，解码器 D 把 z 变回重建 x_hat。先测试 D(E(x))，这条路径没有未来预测器，可以单独暴露 codec 的信息损失。'),P('第 2 步：理解压缩收益与信息损失','较短表示降低后续预测的计算成本，却可能丢失纹理、微小物体或精确位置。如果真实图像经编码解码后已经模糊，不能把所有最终模糊都归因于未来预测模型。','VAE 常让隐表示具有便于采样的概率结构，并通过重建和分布约束共同学习。它不是“任何带瓶颈的编码器”的同义词；不同实现的 latent 缩放也要配套。'),P('第 3 步：连续表示和离散编号都能做序列预测','连续 latent 是一组浮点数，可用数值误差作为目标；VQ 类方法选择码本条目后，也可把编号当分类目标。两者在输出头、损失和采样上不同。','AR 只说明按历史逐步预测，不要求输出必须是离散文字。因此“连续视觉 latent 的 AR”完全可以存在。到底使用 L1、L2 还是其他目标，要看实现。'),P('第 4 步：把项目名称翻译成接口','看到 LSD 或别的内部简称，先定位类定义、构造配置、encode/decode 调用和输出 shape。再确认本次训练是否真正实例化它。代码库支持一个模块，不代表当前运行启用了它。','把 codec、连接层、动态预测器分开画，标记冻结范围。若某个 latent 的通道数或缩放发生变化，下游模型和解码器可能都需要同步修改。')],
 worked:{title:'先测重建，再测预测',steps:['真实帧 x 经 codec 得到 D(E(x))，测重建误差。','再让预测器根据历史预测未来 latent，交给同一解码器。','若第一条路径已丢掉小物体，先研究 codec；若重建清楚而预测错误，再研究动态模型。','两种误差不应未经推导就直接相加解释为总误差。'],takeaway:'拆开组件评测，可以把“看起来效果差”变成更具体的研究问题。'},
 example:{code:'image = [0.0, 1.0, 0.0, 1.0]\nlatent = sum(image)/len(image)\nreconstruction = [latent]*len(image)\nmse = sum((a-b)**2 for a,b in zip(image,reconstruction))/len(image)\nprint("latent", latent)\nprint("reconstruction", reconstruction)\nprint("MSE", mse)',output:'latent 0.5\nreconstruction [0.5, 0.5, 0.5, 0.5]\nMSE 0.25',explanation:'用均值压缩会丢掉位置变化；这是信息丢失的最小例子，不是 VAE 或 LSD 的实现。'},
 checks:[Q('真实图像经过 codec 已丢失细节，首先该检查什么？','暂时移除未来预测器，观察重建路径。','检查 codec 的重建、预处理、缩放和训练目标，而不先盲目增大预测器。',0),Q('连续 latent 能不能使用 AR 预测？','AR 约束的是预测依赖还是数值类型？','可以。AR 约束历史依赖，输出可以连续；对应损失和输出头与离散词表不同。',2)],
 practice:{title:'给视觉链路写一份接口契约',steps:[A('画出编码、连接、预测和解码的接口。','每个箭头写形状、数值类型和归一化方式。','未知的字段标为待查，不根据名字猜。'),A('为 codec 重建设计独立评测。','使用真实输入和重建输出，暂不混入未来预测误差。','比较前对齐分辨率、像素范围和预处理。'),A('记录 LSD 的实际定义位置与待确认的运行配置。','区分项目词、通用方法和当前启用模块。','截图或昵称不能单独证明训练架构。')]},sources:[S.vae,S.vq,S.ldm]
})];
